{"command":"cd /work/workspace/deliverable && python3 - <<'EOF'
import json
d = json.load(open('numeros.json'))
schema = {
  "itbi": {"devido": bool, "base": int, "fundamento": str},
  "integralizacao_imovel": {"valor_recomendado": (int, float), "ganho_capital_pf": (int, float)},
  "pro_labore_minimo_recomendado_mensal": {"Marina": (int, float), "Felipe": (int, float), "Luana": (int, float)},
  "distribuicao_mensal_pretendida": (int, float),
  "irrf_dividendos_2026_estimado_mensal": (int, float),
  "simples_possivel": bool,
}
errs = []
for k, spec in schema.items():
    if k not in d:
        errs.append(f"missing key {k}"); continue
    if isinstance(spec, dict):
        for sub, t in spec.items():
            if sub not in d[k]:
                errs.append(f"missing {k}.{sub}")
            elif not isinstance(d[k][sub], t):
                errs.append(f"bad type {k}.{sub}: {type(d[k][sub]).__name__}")
extra_top = [k for k in d if k not in schema]
extra_nested = {k: [s for s in d[k] if isinstance(d[k], dict) and s not in schema[k]] for k in schema if k in d and isinstance(d[k], dict)}
print("SCHEMA OK" if not errs else "ERRORS: " + "; ".join(errs))
print("extra top-level:", extra_top)
print("extra nested:", extra_nested)
print("itbi:", d["itbi"]["devido"], "| base:", d["itbi"]["base"])
print("integralizacao:", d["integralizacao_imovel"])
print("pro_labore:", d["pro_labore_minimo_recomendado_mensal"])
print("distribuicao_pretendida:", d["distribuicao_mensal_pretendida"])
print("irrf:", d["irrf_dividendos_2026_estimado_mensal"])
print("simples_possivel:", d["simples_possivel"])
EOF"}
